$Controls=@(
 @{id='U01';category='User Auditing';policy='Only Administrator, labadmin, mail.fallback, mail.audit, the existing domain administration group and existing MailEnable service identities are authorized. Disable undocumented interactive identities.'},
 @{id='U02';category='User Auditing';policy='mail.audit is an authorized standard employee. It must remain enabled without local administrator privileges.'},
 @{id='S01';category='Application Security';policy='SSH must reject empty passwords. Preserve organizer keys and password-capable authorized access.'},
 @{id='S02';category='Application Security';policy='SSH forwarding of TCP, agent and streamlocal connections is prohibited on MAIL01.'},
 @{id='S03';category='Application Security';policy='SSH LoginGraceTime must be between 1 and 60 seconds.'},
 @{id='W01';category='Application Security';policy='Disable IIS directory browsing for MailEnable WebMail.'},
 @{id='W02';category='Application Security';policy='Remote webmail clients must receive Custom or DetailedLocalOnly IIS errors.'},
 @{id='W03';category='Application Security';policy='HTTP TRACE requests must be denied by effective IIS request filtering.'},
 @{id='W04';category='Application Security';policy='Webmail maxAllowedContentLength must be between 30000000 and 50000000 bytes; ordinary mail attachments must remain usable.'},
 @{id='L01';category='Local Policy';policy='Enable successful process creation auditing.'},
 @{id='L02';category='Local Policy';policy='Enable successful local user account management auditing.'},
 @{id='L03';category='Local Policy';policy='Enable failed logon auditing.'},
 @{id='P01';category='Local Policy';policy='Configure a nonempty interactive logon caption and notice.'},
 @{id='P02';category='Local Policy';policy='Machine inactivity limit must be 60 through 900 seconds.'},
 @{id='P03';category='Local Policy';policy='Do not allow anonymous enumeration of SAM accounts.'},
 @{id='A01';category='Application Security';policy='Ordinary users may read operations.ps1 in the scenario directory but must not modify it.'},
 @{id='A02';category='Application Security';policy='Ordinary users may read the scenario Maintenance directory but must not create or modify executable content there.'},
 @{id='A03';category='Application Security';policy='Only local Administrators and SYSTEM may read scenario confidential.txt. Preserve its contents.'},
 @{id='A04';category='Application Security';policy='Ordinary users may read the scenario test_authorized_keys fixture but must not modify it. It is inert and is not an organizer access key.'},
 @{id='M01';category='Malware';policy='The inert MailboxCacheSync scheduled task is unauthorized. Disable or remove its activation. Preserve ordinary MailEnable jobs.'},
 @{id='M02';category='Malware';policy='The inert SummitMailLegacy machine startup entry is unauthorized. Remove its activation.'},
 @{id='D01';category='Defensive Countermeasures';policy='The SummitMail-UnnecessaryIngress allow rule is unauthorized. Disable or remove it. Keep all three firewall profiles enabled and retain required business rules.'},
 @{id='O01';category='Operating System Updates';policy='Automatic Windows updates must not be disabled by policy; the Windows Update service must remain installed and must not have Disabled startup. Applying an actual update is separate acceptance work.'},
 @{id='F01';category='Prohibited Files';policy='Remove fictional plaintext training credentials from Operations, including renamed copies. Preserve operations-business.txt.'},
 @{id='F02';category='Prohibited Files';policy='Remove the synthetic personal media archive from Operations, including renamed copies. Preserve business files.'}
)
